BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='2s';
SET LOCAL lock_timeout='1s';
SET LOCAL search_path=pg_catalog;
WITH targets AS (
 SELECT c.* FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relname IN ('book_cohorts','book_cohort_members','seminar_messages')
), browser_roles AS (
 SELECT oid,rolname,rolsuper,rolbypassrls,rolinherit,rolcanlogin FROM pg_catalog.pg_roles WHERE rolname IN ('anon','authenticated','service_role')
)
SELECT jsonb_build_object(
 'tables',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_catalog.pg_get_userbyid(c.relowner),'kind',c.relkind,'is_partition',c.relispartition,'has_subclass',c.relhassubclass,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity) ORDER BY c.relname) FROM targets c),'[]'::jsonb),
 'columns',COALESCE((SELECT jsonb_agg(jsonb_build_object('table',c.relname,'number',a.attnum,'name',a.attname,'type',pg_catalog.format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'collation',CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::regcollation::text END,'default_expression',pg_catalog.pg_get_expr(d.adbin,d.adrelid),'default_md5',pg_catalog.md5(pg_catalog.pg_get_expr(d.adbin,d.adrelid)),'acl',COALESCE((SELECT jsonb_agg(jsonb_build_object('grantor',pg_catalog.pg_get_userbyid(x.grantor),'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY x.grantor,x.grantee,x.privilege_type) FROM pg_catalog.aclexplode(a.attacl) x),'[]'::jsonb)) ORDER BY c.relname,a.attnum) FROM targets c JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum),'[]'::jsonb),
 'constraints',COALESCE((SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype,'validated',k.convalidated,'deferrable',k.condeferrable,'initially_deferred',k.condeferred,'no_inherit',k.connoinherit,'definition',pg_catalog.pg_get_constraintdef(k.oid),'definition_md5',pg_catalog.md5(pg_catalog.pg_get_constraintdef(k.oid))) ORDER BY c.relname,k.conname) FROM targets c JOIN pg_catalog.pg_constraint k ON k.conrelid=c.oid),'[]'::jsonb),
 'indexes',COALESCE((SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',i.relname,'unique',x.indisunique,'primary',x.indisprimary,'valid',x.indisvalid,'ready',x.indisready,'immediate',x.indimmediate,'nulls_not_distinct',x.indnullsnotdistinct,'key_count',x.indnkeyatts,'definition',pg_catalog.pg_get_indexdef(i.oid),'definition_md5',pg_catalog.md5(pg_catalog.pg_get_indexdef(i.oid))) ORDER BY c.relname,i.relname) FROM targets c JOIN pg_catalog.pg_index x ON x.indrelid=c.oid JOIN pg_catalog.pg_class i ON i.oid=x.indexrelid),'[]'::jsonb),
 'triggers',COALESCE((SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'type',t.tgtype,'enabled',t.tgenabled,'internal',t.tgisinternal,'argument_count',t.tgnargs,'update_columns',t.tgattr::text,'deferrable',t.tgdeferrable,'initially_deferred',t.tginitdeferred,'definition',pg_catalog.pg_get_triggerdef(t.oid),'definition_md5',pg_catalog.md5(pg_catalog.pg_get_triggerdef(t.oid)),'function_schema',pn.nspname,'function_name',p.proname,'function_identity_arguments',pg_catalog.pg_get_function_identity_arguments(p.oid),'function_security_definer',p.prosecdef,'function_configuration',p.proconfig) ORDER BY c.relname,t.tgname) FROM targets c JOIN pg_catalog.pg_trigger t ON t.tgrelid=c.oid JOIN pg_catalog.pg_proc p ON p.oid=t.tgfoid JOIN pg_catalog.pg_namespace pn ON pn.oid=p.pronamespace),'[]'::jsonb),
 'policies',COALESCE((SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',ARRAY(SELECT CASE WHEN role_id=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(role_id) END FROM pg_catalog.unnest(p.polroles) role_id),'using_expression',pg_catalog.pg_get_expr(p.polqual,p.polrelid),'using_md5',pg_catalog.md5(pg_catalog.pg_get_expr(p.polqual,p.polrelid)),'check_expression',pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid),'check_md5',pg_catalog.md5(pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid))) ORDER BY c.relname,p.polname) FROM targets c JOIN pg_catalog.pg_policy p ON p.polrelid=c.oid),'[]'::jsonb),
 'table_acls',COALESCE((SELECT jsonb_agg(jsonb_build_object('table',c.relname,'grantor',pg_catalog.pg_get_userbyid(x.grantor),'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY c.relname,x.grantor,x.grantee,x.privilege_type) FROM targets c CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(c.relacl,pg_catalog.acldefault('r',c.relowner))) x),'[]'::jsonb),
 'effective_table_privileges',COALESCE((SELECT jsonb_agg(jsonb_build_object('table',c.relname,'role',r.rolname,'select',pg_catalog.has_table_privilege(r.oid,c.oid,'SELECT'),'insert',pg_catalog.has_table_privilege(r.oid,c.oid,'INSERT'),'update',pg_catalog.has_table_privilege(r.oid,c.oid,'UPDATE'),'delete',pg_catalog.has_table_privilege(r.oid,c.oid,'DELETE'),'truncate',pg_catalog.has_table_privilege(r.oid,c.oid,'TRUNCATE'),'references',pg_catalog.has_table_privilege(r.oid,c.oid,'REFERENCES'),'trigger',pg_catalog.has_table_privilege(r.oid,c.oid,'TRIGGER'),'maintain',pg_catalog.has_table_privilege(r.oid,c.oid,'MAINTAIN')) ORDER BY c.relname,r.rolname) FROM targets c CROSS JOIN browser_roles r),'[]'::jsonb),
 'roles',COALESCE((SELECT jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'bypass_rls',rolbypassrls,'inherit',rolinherit,'login',rolcanlogin) ORDER BY rolname) FROM browser_roles),'[]'::jsonb),
 'role_memberships',COALESCE((SELECT jsonb_agg(jsonb_build_object('granted_role',pg_catalog.pg_get_userbyid(m.roleid),'member_role',pg_catalog.pg_get_userbyid(m.member),'grantor',pg_catalog.pg_get_userbyid(m.grantor),'admin',m.admin_option,'inherit',m.inherit_option,'set',m.set_option) ORDER BY m.roleid,m.member) FROM pg_catalog.pg_auth_members m WHERE m.roleid IN(SELECT oid FROM browser_roles) OR m.member IN(SELECT oid FROM browser_roles)),'[]'::jsonb),
 'default_acls',COALESCE((SELECT jsonb_agg(jsonb_build_object('owner',pg_catalog.pg_get_userbyid(d.defaclrole),'schema',CASE WHEN d.defaclnamespace=0 THEN 'GLOBAL' ELSE d.defaclnamespace::regnamespace::text END,'object_type',d.defaclobjtype,'grantor',pg_catalog.pg_get_userbyid(x.grantor),'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY d.defaclrole,d.defaclnamespace,d.defaclobjtype,x.grantee,x.privilege_type) FROM pg_catalog.pg_default_acl d CROSS JOIN LATERAL pg_catalog.aclexplode(d.defaclacl) x WHERE d.defaclnamespace IN(0,'public'::regnamespace::oid) AND (d.defaclrole IN(SELECT relowner FROM targets) OR x.grantee=0 OR x.grantee IN(SELECT oid FROM browser_roles))),'[]'::jsonb),
 'inheritance',COALESCE((SELECT jsonb_agg(jsonb_build_object('parent',i.inhparent::regclass::text,'child',i.inhrelid::regclass::text,'sequence',i.inhseqno,'detach_pending',i.inhdetachpending) ORDER BY i.inhparent,i.inhrelid) FROM pg_catalog.pg_inherits i WHERE i.inhparent IN(SELECT oid FROM targets) OR i.inhrelid IN(SELECT oid FROM targets)),'[]'::jsonb)
) AS metadata;
COMMIT;
